class Solution:
    def maxArea(self, height: int, positions: List[int], directions: str) -> int:
        pos = positions[:]
        d = list(directions)
        best = s = sum(pos)
        for _ in range(2 * height):
            for i in range(len(pos)):
                if d[i] == 'U':
                    pos[i] += 1
                    if pos[i] == height: d[i] = 'D'
                else:
                    pos[i] -= 1
                    if pos[i] == 0: d[i] = 'U'
            s = sum(pos)
            best = max(best, s)
        return best

