class Solution {
public:
    long long maxArea(int height, vector<int>& positions, string directions) {
        int n = positions.size();
        vector<int> pos = positions;
        vector<char> d(directions.begin(), directions.end());
        long long best = 0, s = 0;
        for (int v : pos) s += v;
        best = s;
        for (int t = 0; t < 2 * height; t++) {
            for (int i = 0; i < n; i++) {
                if (d[i] == 'U') { if (++pos[i] == height) d[i] = 'D'; }
                else { if (--pos[i] == 0) d[i] = 'U'; }
            }
            s = 0;
            for (int v : pos) s += v;
            best = max(best, s);
        }
        return best;
    }
};

