class Solution:
    def maxArea(self, height: int, positions: List[int], directions: str) -> int:
        T = 2 * height
        slope = [0] * (T + 1)
        cur = 0
        for x, dr in zip(positions, directions):
            cur += x
            if dr == 'U':
                s0, b1, b2 = 1, height - x, T - x
            else:
                s0, b1, b2 = -1, x, x + height
            if b1 <= 0:
                s0 = -s0
            else:
                slope[b1] -= 2 * s0
            if 0 < b2 < T:
                slope[b2] += 2 * s0
            slope[0] += s0
        best, s = cur, slope[0]
        for t in range(1, T):
            s += slope[t]
            cur += s
            best = max(best, cur)
        return best

