class Solution {
public:
    long long maxArea(int height, vector<int>& positions, string directions) {
        int T = 2 * height;
        vector<long long> slope(T + 1, 0);
        long long cur = 0;
        for (int i = 0; i < (int)positions.size(); i++) {
            int x = positions[i];
            cur += x;
            bool up = directions[i] == 'U';
            int s0 = up ? 1 : -1;
            int b1 = up ? height - x : x;
            int b2 = up ? T - x : x + height;
            if (b1 <= 0) s0 = -s0; else slope[b1] -= 2LL * s0;
            if (b2 > 0 && b2 < T) slope[b2] += 2LL * s0;
            slope[0] += s0;
        }
        long long best = cur, s = slope[0];
        for (int t = 1; t < T; t++) {
            s += slope[t];
            cur += s;
            best = max(best, cur);
        }
        return best;
    }
};

